use EIPSI\ExternalApi as A;
d2_case('Operations health is local and defaults retain API2B limits',function(){$c=A\OperationsSettings::get();d2_assert($c['export_ttl']===86400&&$c['export_bytes']===268435456&&$c['aggregate_bytes']===1073741824);$h=A\ExternalApiHealth::inspect();d2_assert($h['checks']['schema']['state']==='OK'&&$h['scope']==='CURRENT_BLOG_PREFIX');});
function q3_case($name,$fn){d2_case($name,function()use($fn){$prior=get_option(A\OperationsSettings::OPTION,null);$state=get_option(A\Operations::STATE_OPTION,null);try{$fn();}finally{if($prior===null)delete_option(A\OperationsSettings::OPTION);else update_option(A\OperationsSettings::OPTION,$prior,false);if($state===null)delete_option(A\Operations::STATE_OPTION);else update_option(A\Operations::STATE_OPTION,$state,false);}});}
function q3_values($change=array()){$v=A\OperationsSettings::get();unset($v['revision']);return array_replace($v,$change);}
function q3_save($change=array()){$c=A\OperationsSettings::get();return A\OperationsSettings::save(q3_values($change),$c['revision']);}
function q3_request($action,$extra=array()){$old=$_SERVER['REQUEST_METHOD']??'GET';$_SERVER['REQUEST_METHOD']='POST';try{return A\Admin::dispatch(array_merge(array('operation'=>$action,'nonce'=>wp_create_nonce('eipsi_external_api')),$extra));}finally{$_SERVER['REQUEST_METHOD']=$old;}}
